var n=`1193-jocon`;var t=`world-1193`;var a=`GT`;var o=`central-america-caribbean`;var r=4;var s=103;var l={en:`Jocón`,ua:`Хокон`};var c={en:`Jocón is a dish from Guatemala prepared with tomatillo, cilantro, serrano pepper, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Хокон, страва кухні країни Гватемала, яку готують із таких продуктів: томатильйо, кінза, перець серрано, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`tomatillo`,500,`g`],[`cilantro`,70,`g`],[`serrano-pepper`,2,`pcs`],[`garlic`,4,`clove`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,190,`g`],[`canola-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`chicken-thigh`,850,`g`],[`chicken-stock`,650,`ml`]]},{en:`Continue simmering the sauce from the previous step uncovered until concentrated and thick enough to coat the ingredients.`,ua:`Продовжуйте виварювати соус із попереднього етапу без кришки, доки він загусне та вкриватиме складники.`,t:[`reducing-sauce`],m:10,i:[]},{en:`Cook the accompanying rice separately with its measured water; serve with thoroughly cooked chicken and green tomatillo-cilantro sauce.`,ua:`Зваріть рис окремо у зазначеній воді; подавайте з повністю приготованою куркою й зеленим соусом із томатільйо та кінзи.`,t:[`rice-washing`,`absorption-cooking`],m:21,i:[[`white-rice`,350,`g`],[`water`,560,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`table-salt`,null,`to_taste`]]}];var h={slug:n,id:t,country:`GT`,region:o,servings:4,minutes:103,title:l,text:c,steps:g};export{a as country,h as default,t as id,s as minutes,o as region,r as servings,n as slug,g as steps,c as text,l as title};